effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN. Every read of the source goes through the layer transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }

// HSV -> RGB. The smoothstep on the ramp removes the hard kinks the naive
// piecewise version prints at every 60 degrees.
vec3 hsv2rgb(vec3 c){
vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
rgb = rgb * rgb * (3.0 - 2.0 * rgb);
return c.z * mix(vec3(1.0), rgb, clamp(c.y, 0.0, 1.0));
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;
float l  = lum(sc);

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  c0  = centre - vec2(0.5);
c0.x *= asp;
vec2  q   = lp - vec2(0.5);
q.x *= asp;
q -= c0;

float ang = radians(angle);
vec2  ax  = vec2(cos(ang), sin(ang));

// ---- hue driver ---------------------------------------------------------
float h;
if (rainbowMode <= 0){
h = l;
} else if (rainbowMode <= 1){
// Position Axis - the projection of the layer coordinate onto a rotatable
// direction, so the bands can be laid down at any angle.
h = dot(lp - vec2(0.5), ax) + 0.5;
} else if (rainbowMode <= 2){
h = length(q) * 1.6;
} else if (rainbowMode <= 3){
// Angle - atan2 around the centre. Wrapping is handled by fract() below, so
// the seam at -pi never shows as a hard edge.
h = atan(q.y, q.x) / 6.2831853 + 0.5;
} else if (rainbowMode <= 4){
h = fract(acTime * 0.15);
} else {
h = (l + dot(lp - vec2(0.5), ax) + 0.5) * 0.5;
}

h = mix(h, l, clamp(lumaWeight, 0.0, 1.0));

// Grain breaks the banding a pure gradient shows on 8-bit output.
if (grain > 0.001){
h += (h21(floor(lp * max(acLayerSize.y, 1.0) * 0.5)) - 0.5) * grain * 0.08;
}

// ---- hue shaping --------------------------------------------------------
// hueRange compresses the sweep around the midpoint; above 1.0 it over-extends
// so the spectrum wraps past red back into red.
h = 0.5 + (h - 0.5) * hueRange;
h = h * cycles + phase / 360.0 + hueShift / 360.0;

vec3 rainbow = hsv2rgb(vec3(fract(h), saturation, brightness));

// ---- composite ----------------------------------------------------------
vec3 blended;
if (blendMode <= 0){
blended = rainbow;
} else if (blendMode <= 1){
blended = sc * rainbow * 2.0;
} else if (blendMode <= 2){
blended = vec3(1.0) - (vec3(1.0) - sc) * (vec3(1.0) - rainbow);
} else if (blendMode <= 3){
blended = sc + rainbow;
} else {
// Soft Light, softened transition instead of a hard step at 0.5.
vec3 m = smoothstep(vec3(0.45), vec3(0.55), rainbow);
blended = mix(2.0 * sc * rainbow + sc * sc * (1.0 - 2.0 * rainbow),
              sqrt(max(sc, vec3(0.0))) * (2.0 * rainbow - 1.0) + 2.0 * sc * (1.0 - rainbow),
              m);
}
blended = sat3v(blended);

vec3  col = mix(sc, blended, clamp(blendAmt, 0.0, 1.0));
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
